import os

import pytest
from utils.llm_data import llm_models_root
from utils.util import force_ampere, similar

from tensorrt_llm import LLM, SamplingParams
from tensorrt_llm._torch.pyexecutor.llm_request import (LlmRequest,
                                                        SamplingConfig)
from tensorrt_llm.llmapi.llm_utils import KvCacheConfig


@pytest.fixture(scope="module")
def input_prompts():
    return [
        "Born in north-east France, Soyer trained as a",
        "The future of AI is",
    ]


@pytest.fixture(scope="module")
def expected_outputs():
    return {
        "Born in north-east France, Soyer trained as a": [
            "lawyer and was a member of the French Resistance",
            "cook before turning to painting."
        ],
        "The future of AI is": [
            "all about human-machine collaboration.",
            "more promising than you think."
        ],
    }


@pytest.fixture(scope="module")
def llm():
    return LLM(model=os.path.join(llm_models_root(), "llama-models-v2",
                                  "TinyLlama-1.1B-Chat-v1.0"),
               kv_cache_config=KvCacheConfig(max_tokens=1000),
               max_batch_size=8,
               max_seq_len=64,
               disable_overlap_scheduler=True)


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("n", [1, 2, 3])
def test_create_child_request(n: int):
    sampling_config = SamplingConfig()
    setattr(sampling_config, 'top_p', [0.9])
    setattr(sampling_config, 'num_return_sequences', n)

    parent = LlmRequest(
        request_id=1,
        max_new_tokens=10,
        input_tokens=[1, 2, 3],
        sampling_config=sampling_config,
        is_streaming=False,
        client_id=50,
        return_log_probs=True,
        return_context_logits=True,
    )

    for child_id in range(
            parent.request_id + 1,
            parent.request_id + parent.sampling_config.num_return_sequences):
        parent.create_child_request(child_id)

    assert len(parent.child_requests
               ) == parent.sampling_config.num_return_sequences - 1

    for ind, child in enumerate(parent.child_requests):
        assert child.request_id == ind + parent.request_id + 1
        assert child.py_request_id == child.request_id
        assert child.parent_request_id == parent.request_id

        assert child.py_client_id == 50
        assert child.py_max_new_tokens == 10

        assert child.py_return_log_probs == parent.py_return_log_probs
        assert child.py_return_context_logits == parent.py_return_context_logits

        assert child.py_batch_idx is None

        # Verify parent - child independence
        assert child.py_result is not None
        assert child.py_result is not parent.py_result
        assert child.get_tokens() == parent.get_tokens()
        assert child.get_tokens() is not parent.get_tokens()

        assert child.child_requests == []


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("n", [2])
@pytest.mark.parametrize("best_of", [None, 3])
@pytest.mark.threadleak(enabled=False)
def test_n_outputs(n: int, best_of: int, llm, input_prompts, expected_outputs):
    sampling_params = SamplingParams(
        n=n,
        best_of=best_of,
        temperature=0.8,  # ensure different outputs
        top_p=0.95,  # ensure different outputs
        use_beam_search=False)
    for output_idx, output in enumerate(
            llm.generate(input_prompts, sampling_params=sampling_params)):

        assert len(output.outputs) == n

        for idx, sequence in enumerate(output.outputs):
            if n == best_of:
                assert similar(sequence.text,
                               expected_outputs[input_prompts[output_idx]][idx])


@pytest.mark.parametrize("n", [3])
@pytest.mark.threadleak(enabled=False)
def test_async_n_outputs(n: int, llm, input_prompts):
    sampling_params = SamplingParams(
        n=n,
        temperature=0.8,  # ensure different outputs
        top_p=0.95,  # ensure different outputs
        use_beam_search=False)

    # Asynchronously submit many requests to exceed max batch size.
    futures = []
    for _ in range(5):
        for prompt in input_prompts:
            future = llm.generate_async(prompt, sampling_params)
            futures.append(future)

    # Expect no error raised and each result contains n outputs.
    for _, future in enumerate(futures):
        request_output = future.result()
        assert len(request_output.outputs) == n

#!/usr/bin/env python3
import os
from typing import Optional

import click

from tensorrt_llm import LLM as TorchLLM
from tensorrt_llm._tensorrt_engine import LLM
from tensorrt_llm.llmapi import KvCacheConfig, SamplingParams


@click.command()
@click.option("--model_dir", type=str, required=True)
@click.option("--tp_size", type=int, required=True)
@click.option("--engine_dir", type=str, default=None)
@click.option("--n", type=int, default=1)
@click.option("--best_of", type=int, default=None)
@click.option("--top_k", type=int, default=1)
@click.option("--use_beam_search", is_flag=True)
@click.option("--use_pytorch", is_flag=True)
def main(model_dir: str, tp_size: int, engine_dir: Optional[str], n: int,
         best_of: Optional[int], top_k: int, use_beam_search: bool,
         use_pytorch: bool):
    if use_pytorch:
        llm = TorchLLM(
            model_dir,
            tensor_parallel_size=tp_size,
            kv_cache_config=KvCacheConfig(free_gpu_memory_fraction=0.4))
    else:
        llm = LLM(model_dir,
                  tensor_parallel_size=tp_size,
                  kv_cache_config=KvCacheConfig(free_gpu_memory_fraction=0.4))

    if engine_dir is not None and os.path.abspath(
            engine_dir) != os.path.abspath(model_dir):
        llm.save(engine_dir)

    sampling_params = SamplingParams(max_tokens=10,
                                     end_id=-1,
                                     n=n,
                                     best_of=best_of,
                                     use_beam_search=use_beam_search,
                                     top_k=top_k)
    print(sampling_params)
    prompt_token_ids = [45, 12, 13]
    for output in llm.generate([prompt_token_ids],
                               sampling_params=sampling_params):
        print(output)

    print("run_llm.py Done")


if __name__ == '__main__':
    main()

from difflib import SequenceMatcher

import pytest
import torch
from utils.llm_data import llm_models_root

from tensorrt_llm import LLM, SamplingParams
from tensorrt_llm.llmapi import CudaGraphConfig, KvCacheConfig


@pytest.mark.parametrize(
    "model_name",
    ["Llama-4-Maverick-17B-128E-Instruct", "Llama-4-Scout-17B-16E-Instruct"],
    ids=['maverick', 'scout'])
@pytest.mark.parametrize("backend", ["TRTLLM", "FLASHINFER"],
                         ids=["trtllm", "flashinfer"])
@pytest.mark.parametrize("tp_size", [1, 8], ids=["tp1", "tp8"])
@pytest.mark.parametrize("use_cuda_graph", [True, False],
                         ids=["enable_graph", "disable_graph"])
@pytest.mark.parametrize("enable_attention_dp", [True, False],
                         ids=["enable_adp", "disable_adp"])
@pytest.mark.parametrize("ep_size", [4, 1], ids=["ep4", "ep1"])
@pytest.mark.parametrize("pp_size", [1, 8], ids=["pp1", "pp8"])
def test_llama4(model_name, backend, tp_size, use_cuda_graph,
                enable_attention_dp, ep_size, pp_size):
    if pp_size > 1 and (ep_size > 1 or tp_size > 1):
        return

    if pp_size == 1 and tp_size == 1:
        return

    if enable_attention_dp and not (tp_size == 8 and ep_size == 4
                                    and pp_size == 1):
        pytest.skip("Skip this attention DP test case to avoid too many tests")

    prompts = [
        {
            "prompt": "The president of the United States is"
        },
        {
            # NOTE: Long context accuracy testing (RULER) is not available in CI yet.
            # This test cannot be removed until long context is covered.
            "prompt":
            "This is a very long prompt to exercise long context. Count up to 10000 from 1, 2, 3,"
            + ", ".join(str(i) for i in range(4, 9000))
        },
        {
            "prompt": "<|image|>This image is of color",
            "multi_modal_data": {
                "image": [torch.ones(3, 1024, 1024)]
            }
        },
    ]

    expected_outputs = [
        " the head of state and head of government of the", ", 9000, 9001, ",
        " white. What is the color of the background of"
    ]

    pytorch_config = dict(attn_backend=backend)
    model_dir = str(llm_models_root() / "llama4-models" / model_name)

    kv_cache_config = KvCacheConfig(free_gpu_memory_fraction=0.25, )
    llm = LLM(
        model=model_dir,
        tensor_parallel_size=tp_size,
        moe_expert_parallel_size=ep_size,
        moe_tensor_parallel_size=tp_size // ep_size,
        cuda_graph_config=CudaGraphConfig() if use_cuda_graph else None,
        **pytorch_config,
        pipeline_parallel_size=pp_size,
        enable_attention_dp=enable_attention_dp,
        kv_cache_config=kv_cache_config,
        enable_chunked_prefill=True,
    )
    with llm:
        outputs = llm.generate(
            prompts,
            sampling_params=SamplingParams(max_tokens=10),
        )

    assert len(outputs) == len(expected_outputs), "Output length mismatch"

    def similar(a, b, threshold=0.9):
        return SequenceMatcher(None, a, b).ratio() >= threshold

    for output, expected in zip(outputs, expected_outputs):
        output_text = output.outputs[0].text
        assert similar(
            output_text,
            expected), f"Expected '{expected}' but get '{output_text}'"

#!/usr/bin/env python3
import os
from typing import Optional

import click

from tensorrt_llm._tensorrt_engine import LLM as TrtLLM
from tensorrt_llm.llmapi import LLM, BuildConfig, SamplingParams


@click.command()
@click.option("--model_dir", type=str, required=True)
@click.option("--tp_size", type=int, default=1)
@click.option("--engine_dir", type=str, default=None)
@click.option("--backend", type=str, default=None)
def main(model_dir: str, tp_size: int, engine_dir: str, backend: Optional[str]):
    build_config = BuildConfig()
    build_config.max_batch_size = 8
    build_config.max_input_len = 256
    build_config.max_seq_len = 512

    backend = backend or "tensorrt"
    assert backend in ["pytorch", "tensorrt"]

    llm_cls = TrtLLM if backend == "tensorrt" else LLM

    kwargs = {} if backend == "pytorch" else {"build_config": build_config}

    llm = llm_cls(model_dir, tensor_parallel_size=tp_size, **kwargs)

    if engine_dir is not None and os.path.abspath(
            engine_dir) != os.path.abspath(model_dir):
        llm.save(engine_dir)

    sampling_params = SamplingParams(max_tokens=10, end_id=-1)

    prompt_token_ids = [45, 12, 13]
    for output in llm.generate([prompt_token_ids],
                               sampling_params=sampling_params):
        print(output)


if __name__ == '__main__':
    main()

import asyncio
import copy
import time
from enum import Enum
from typing import List

from tensorrt_llm.scaffolding import (Controller, ParallelProcess,
                                      ScaffoldingLlm, Task, TaskStatus, Worker)


class DummyTask(Task):

    def __init__(self, turn: int):
        self.turn = turn
        self.numbers = []

    @staticmethod
    def create_from_prompt(prompt: str) -> "DummyTask":
        task = DummyTask(2)
        return task

    def create_scaffolding_output(self):
        self.verify()
        return None

    def verify(self):
        for i in range(len(self.numbers)):
            assert self.numbers[i] == i, "task.numbers[i] should be i"


class DummyControllerBase(Controller):

    def generate(self, prompt: str, **kwargs):
        task = DummyTask.create_from_prompt(prompt)
        yield from self.process([task], **kwargs)
        return task.create_scaffolding_output()


# Controller that yields task.turn times for each task
class DummyController(DummyControllerBase):

    class WorkerTag(Enum):
        DUMMY = "dummy"

    def process(self, tasks: List[Task], **kwargs):
        yield_tasks = tasks
        while len(yield_tasks) > 0:
            new_tasks = []
            for task in yield_tasks:
                if len(task.numbers) < task.turn:
                    task.worker_tag = self.WorkerTag.DUMMY
                    new_tasks.append(task)
            yield_tasks = new_tasks

            if len(yield_tasks) > 0:
                yield yield_tasks


# The flag to enable parallel process
# We can use this flag to compare the performance of parallel process
# and sequence process
ENABLE_PARALLEL_PROCESS = True


class DummyParallelController(DummyControllerBase):

    def __init__(self, controllers):
        self.controllers = controllers

    def process(self, tasks: List[Task], **kwargs):
        global ENABLE_PARALLEL_PROCESS
        if ENABLE_PARALLEL_PROCESS:
            tasks_list = [
                copy.deepcopy(tasks) for _ in range(len(self.controllers))
            ]

            kwargs_list = [kwargs for _ in range(len(self.controllers))]

            yield ParallelProcess(self.controllers, tasks_list, kwargs_list)

            tasks = tasks_list[0]
        else:
            original_tasks = copy.deepcopy(tasks)
            for controller in self.controllers:
                tasks = copy.deepcopy(original_tasks)
                yield from controller.process(tasks, **kwargs)


class DummyWorker(Worker):

    async def dummy_handler(self, task: DummyTask):
        await asyncio.sleep(1)
        task.numbers.append(len(task.numbers))
        return TaskStatus.SUCCESS

    task_handlers = {DummyTask: dummy_handler}


def parallel_process_helper_run_and_verify(controllers):
    # Obtain the generator from parallel_process_helper.
    parallel_controller = DummyParallelController(controllers)
    worker = DummyWorker()
    llm = ScaffoldingLlm(parallel_controller,
                         {DummyController.WorkerTag.DUMMY: worker})

    global ENABLE_PARALLEL_PROCESS
    ENABLE_PARALLEL_PROCESS = True
    start_time = time.time()
    llm.generate("")
    end_time = time.time()
    print('Parallel process time:', end_time - start_time)

    ENABLE_PARALLEL_PROCESS = False
    start_time = time.time()
    llm.generate("")
    end_time = time.time()
    print('Sequence process time:', end_time - start_time)

    llm.shutdown()


def test_parallel_process_helper():
    NUM_CONTROLLERS = 3
    controllers = []

    for _ in range(NUM_CONTROLLERS):
        controller = DummyController()
        controllers.append(controller)

    parallel_process_helper_run_and_verify(controllers)


def test_parallel_process_helper_with_two_level():
    NUM_CONTROLLERS_LEVEL_1 = 2
    NUM_CONTROLLERS_LEVEL_2 = 2

    controllers_level_1 = []

    for _ in range(NUM_CONTROLLERS_LEVEL_1):
        controller = DummyController()
        controllers_level_1.append(controller)

    parallel_controller = DummyParallelController(controllers_level_1)
    controllers_level_2 = [parallel_controller]

    for _ in range(NUM_CONTROLLERS_LEVEL_2):
        controller = DummyController()
        controllers_level_2.append(controller)

    parallel_process_helper_run_and_verify(controllers_level_2)

import os

import pytest
from utils.llm_data import llm_models_root
from utils.util import force_ampere, similar

from tensorrt_llm import LLM, SamplingParams
from tensorrt_llm.llmapi import CudaGraphConfig, KvCacheConfig


@pytest.fixture(scope="module")
def input_prompts():
    return [
        "Born in north-east France, Soyer trained as a",
        "The future of AI is",
    ]


@pytest.fixture(scope="module")
def expected_outputs():
    return {
        "Born in north-east France, Soyer trained as a": [
            "painter in Paris before moving to London in",
            "painter and sculptor in Paris before moving"
        ],
        "The future of AI is":
        ["bright, but it's not without", "bright, but it's not going"],
    }


@pytest.fixture(scope="module")
def fixed_params():
    return {"max_tokens": 8, "max_beam_width": 2}


@pytest.fixture(scope="module")
def llm(fixed_params, input_prompts):
    return LLM(
        model=os.path.join(llm_models_root(), "llama-models-v2",
                           "TinyLlama-1.1B-Chat-v1.0"),
        kv_cache_config=KvCacheConfig(max_tokens=10000),
        max_batch_size=fixed_params["max_beam_width"] * len(
            input_prompts
        ),  # use small batch size to prevent large buffers from possibly hiding wrong data accesses.
        max_seq_len=32,
        max_beam_width=fixed_params["max_beam_width"],
        disable_overlap_scheduler=True,
        cuda_graph_config=None,
    )


@pytest.fixture(scope="module")
def llm_cuda_graph(fixed_params, input_prompts):
    return LLM(
        model=os.path.join(llm_models_root(), "llama-models-v2",
                           "TinyLlama-1.1B-Chat-v1.0"),
        kv_cache_config=KvCacheConfig(max_tokens=10000),
        max_batch_size=fixed_params["max_beam_width"] * len(
            input_prompts
        ),  # use small batch size to prevent large buffers from possibly hiding wrong data accesses.
        max_seq_len=32,
        max_beam_width=fixed_params["max_beam_width"],
        disable_overlap_scheduler=False,
        cuda_graph_config=CudaGraphConfig(batch_sizes=[1, 2, 4, 8],
                                          enable_padding=True),
    )


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("return_log_probs", [True, False])
@pytest.mark.parametrize("gather_generation_logits", [True, False])
@pytest.mark.parametrize("gather_context_logits", [True, False])
@pytest.mark.parametrize("num_output_beams", [1, 2])
@pytest.mark.parametrize("num_prompts", [1, 2])
@pytest.mark.threadleak(enabled=False)
def test_beam_search_output_shapes(gather_context_logits: bool,
                                   gather_generation_logits: bool,
                                   return_log_probs: bool,
                                   num_output_beams: int, num_prompts: int, llm,
                                   fixed_params, input_prompts,
                                   expected_outputs):
    if return_log_probs and num_prompts > 1:
        pytest.skip(
            "Beam search currently does not support return_log_probs with multiple prompts"
        )
    sampling_params = SamplingParams(
        max_tokens=fixed_params["max_tokens"],
        n=num_output_beams,
        best_of=fixed_params["max_beam_width"],
        use_beam_search=True,
        return_context_logits=gather_context_logits,
        return_generation_logits=gather_generation_logits,
        logprobs=return_log_probs,
    )
    outputs = llm.generate(input_prompts[:num_prompts],
                           sampling_params=sampling_params)
    assert len(outputs) == num_prompts
    for output_idx, output in enumerate(outputs):
        if gather_context_logits:
            assert output.context_logits is not None
            assert len(
                output.prompt_token_ids) == output.context_logits.shape[0]
        else:
            assert output.context_logits is None
        assert len(output.outputs) == num_output_beams
        for beam_idx, beam in enumerate(output.outputs):
            if gather_generation_logits:
                gen_logits = beam.generation_logits
                assert gen_logits is not None
                assert gen_logits.ndim == 2
                assert gen_logits.shape[0] == sampling_params.max_tokens
            else:
                assert beam.generation_logits is None

            if return_log_probs:
                assert len(beam.logprobs) == sampling_params.max_tokens
            else:
                assert len(beam.logprobs) == 0
            # Check output similarity
            assert similar(
                beam.text,
                expected_outputs[input_prompts[output_idx]][beam_idx])


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("return_log_probs", [True, False])
@pytest.mark.parametrize("gather_generation_logits", [True, False])
@pytest.mark.parametrize("gather_context_logits", [True, False])
@pytest.mark.parametrize("num_output_beams", [1, 2])
@pytest.mark.parametrize("num_prompts", [1, 2, 3])
@pytest.mark.threadleak(enabled=False)
def test_beam_search_output_shapes_cuda_graph_and_overlap(
        gather_context_logits: bool, gather_generation_logits: bool,
        return_log_probs: bool, num_output_beams: int, num_prompts: int,
        llm_cuda_graph, fixed_params, input_prompts, expected_outputs):
    if return_log_probs and num_prompts > 1:
        pytest.skip(
            "Beam search currently does not support return_log_probs with multiple prompts"
        )
    sampling_params = SamplingParams(
        max_tokens=fixed_params["max_tokens"],
        n=num_output_beams,
        best_of=fixed_params["max_beam_width"],
        use_beam_search=True,
        return_context_logits=gather_context_logits,
        return_generation_logits=gather_generation_logits,
        logprobs=return_log_probs,
    )
    # test padding of cuda graph with 3 prompts
    # replicate the prompts to have more than 2 prompts available
    if (num_prompts == 3 and len(input_prompts) == 2):
        input_prompts = [input_prompts[0]] * 3
    outputs = llm_cuda_graph.generate(input_prompts[:num_prompts],
                                      sampling_params=sampling_params)
    assert len(outputs) == num_prompts
    for output_idx, output in enumerate(outputs):
        if gather_context_logits:
            assert output.context_logits is not None
            assert len(
                output.prompt_token_ids) == output.context_logits.shape[0]
        else:
            assert output.context_logits is None
        assert len(output.outputs) == num_output_beams
        for beam_idx, beam in enumerate(output.outputs):
            if gather_generation_logits:
                gen_logits = beam.generation_logits
                assert gen_logits is not None
                assert gen_logits.ndim == 2
                assert gen_logits.shape[0] == sampling_params.max_tokens
            else:
                assert beam.generation_logits is None

            if return_log_probs:
                assert len(beam.logprobs) == sampling_params.max_tokens
            else:
                assert len(beam.logprobs) == 0
            # Check output similarity
            assert similar(
                beam.text,
                expected_outputs[input_prompts[output_idx]][beam_idx])

import copy
from enum import Enum
from typing import List

from tensorrt_llm.scaffolding import (Controller, ParallelProcess,
                                      ScaffoldingLlm, Task, TaskCollection,
                                      TaskStatus, Worker, with_task_collection)


class DummyTask(Task):

    def __init__(self):
        self.before_flag = False
        self.after_flag = False

    @staticmethod
    def create_from_prompt(prompt: str) -> "DummyTask":
        task = DummyTask()
        return task

    def create_scaffolding_output(self):
        return None

    def verify(self):
        assert self.before_flag, "task.before_flag has not been set to True"
        assert self.after_flag, "task.after_flag has not been set to True"


class DummyTaskCollection(TaskCollection):

    def __init__(self):
        super().__init__()
        self.task_count = 0

    def before_yield(self, tasks: List[Task]):
        for task in tasks:
            task.before_flag = True

    def after_yield(self, tasks: List[Task]):
        for task in tasks:
            task.after_flag = True
            self.task_count += 1


class DummyControllerBase(Controller):

    class WorkerTag(Enum):
        DUMMY = "dummy"

    def __init__(self, expected_task_count: int):
        super().__init__()
        self.expected_task_count = expected_task_count

    def generate(self, prompt: str, **kwargs):
        task = DummyTask.create_from_prompt(prompt)
        yield from self.process([task], **kwargs)
        return task.create_scaffolding_output()

    def verify(self):
        assert self.task_collections[
            "dummy"].task_count == self.expected_task_count, (
                "task count is not as expected")


@with_task_collection("dummy", DummyTaskCollection)
# verify that we can have multiple task collections and they works separately
@with_task_collection("dummy2", DummyTaskCollection)
class DummyController(DummyControllerBase):

    def process(self, tasks: List[Task], **kwargs):
        for task in tasks:
            task.worker_tag = self.WorkerTag.DUMMY

        yield tasks

        for task in tasks:
            task.verify()

        self.verify()


@with_task_collection("dummy", DummyTaskCollection)
class DummyParallelController(DummyControllerBase):

    def __init__(self, controllers):
        expected_task_count = sum(
            [controller.expected_task_count for controller in controllers])
        super().__init__(expected_task_count)
        self.controllers = controllers

    def process(self, tasks: List[Task], **kwargs):
        tasks_list = [
            copy.deepcopy(tasks) for _ in range(len(self.controllers))
        ]

        kwargs_list = [kwargs for _ in range(len(self.controllers))]

        yield ParallelProcess(self.controllers, tasks_list, kwargs_list)

        for tasks in tasks_list:
            for task in tasks:
                task.verify()

        tasks = tasks_list[0]
        self.verify()


class DummyWorker(Worker):

    async def dummy_handler(self, task: DummyTask):
        return TaskStatus.SUCCESS

    task_handlers = {DummyTask: dummy_handler}


def run(controller, expected_task_count):
    worker = DummyWorker()
    llm = ScaffoldingLlm(controller, {DummyController.WorkerTag.DUMMY: worker})

    llm.generate("")
    llm.shutdown()


def test_dummy_task_collection():
    controller = DummyController(1)
    run(controller, 1)

    controller = DummyParallelController(
        [DummyController(1), DummyController(1)])
    run(controller, 2)

