        model=os.path.join(llm_models_root(), "llama-models-v2",
                           "TinyLlama-1.1B-Chat-v1.0"),
        kv_cache_config=KvCacheConfig(max_tokens=10000),
        max_batch_size=fixed_params["max_beam_width"] * len(
            input_prompts
        ),  # use small batch size to prevent large buffers from possibly hiding wrong data accesses.
        max_seq_len=32,
        max_beam_width=fixed_params["max_beam_width"],
        disable_overlap_scheduler=False,
        cuda_graph_config=CudaGraphConfig(batch_sizes=[1, 2, 4, 8],
                                          enable_padding=True),
    )


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("return_log_probs", [True, False])
@pytest.mark.parametrize("gather_generation_logits", [True, False])
@pytest.mark.parametrize("gather_context_logits", [True, False])
@pytest.mark.parametrize("num_output_beams", [1, 2])
@pytest.mark.parametrize("num_prompts", [1, 2])
@pytest.mark.threadleak(enabled=False)
def test_beam_search_output_shapes(gather_context_logits: bool,
                                   gather_generation_logits: bool,
                                   return_log_probs: bool,
                                   num_output_beams: int, num_prompts: int, llm,
                                   fixed_params, input_prompts,
                                   expected_outputs):
    if return_log_probs and num_prompts > 1:
        pytest.skip(
            "Beam search currently does not support return_log_probs with multiple prompts"
        )
    sampling_params = SamplingParams(
        max_tokens=fixed_params["max_tokens"],
        n=num_output_beams,
        best_of=fixed_params["max_beam_width"],
        use_beam_search=True,
        return_context_logits=gather_context_logits,
        return_generation_logits=gather_generation_logits,
        logprobs=return_log_probs,
    )
    outputs = llm.generate(input_prompts[:num_prompts],
                           sampling_params=sampling_params)
    assert len(outputs) == num_prompts
    for output_idx, output in enumerate(outputs):
        if gather_context_logits:
            assert output.context_logits is not None
            assert len(
                output.prompt_token_ids) == output.context_logits.shape[0]
        else:
            assert output.context_logits is None
        assert len(output.outputs) == num_output_beams
        for beam_idx, beam in enumerate(output.outputs):
            if gather_generation_logits:
                gen_logits = beam.generation_logits
                assert gen_logits is not None
                assert gen_logits.ndim == 2
                assert gen_logits.shape[0] == sampling_params.max_tokens
            else:
                assert beam.generation_logits is None

            if return_log_probs:
                assert len(beam.logprobs) == sampling_params.max_tokens
            else:
                assert len(beam.logprobs) == 0
            # Check output similarity
            assert similar(
                beam.text,
                expected_outputs[input_prompts[output_idx]][beam_idx])


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("return_log_probs", [True, False])
@pytest.mark.parametrize("gather_generation_logits", [True, False])
@pytest.mark.parametrize("gather_context_logits", [True, False])
@pytest.mark.parametrize("num_output_beams", [1, 2])
@pytest.mark.parametrize("num_prompts", [1, 2, 3])
@pytest.mark.threadleak(enabled=False)
def test_beam_search_output_shapes_cuda_graph_and_overlap(
        gather_context_logits: bool, gather_generation_logits: bool,
        return_log_probs: bool, num_output_beams: int, num_prompts: int,
        llm_cuda_graph, fixed_params, input_prompts, expected_outputs):
    if return_log_probs and num_prompts > 1:
        pytest.skip(
            "Beam search currently does not support return_log_probs with multiple prompts"
        )
    sampling_params = SamplingParams(
        max_tokens=fixed_params["max_tokens"],
        n=num_output_beams,
        best_of=fixed_params["max_beam_width"],
        use_beam_search=True,
        return_context_logits=gather_context_logits,
        return_generation_logits=gather_generation_logits,
        logprobs=return_log_probs,
    )
    # test padding of cuda graph with 3 prompts
    # replicate the prompts to have more than 2 prompts available
    if (num_prompts == 3 and len(input_prompts) == 2):
        input_prompts = [input_prompts[0]] * 3
    outputs = llm_cuda_graph.generate(input_prompts[:num_prompts],
                                      sampling_params=sampling_params)
    assert len(outputs) == num_prompts
    for output_idx, output in enumerate(outputs):
        if gather_context_logits:
            assert output.context_logits is not None
            assert len(
                output.prompt_token_ids) == output.context_logits.shape[0]
        else:
            assert output.context_logits is None
        assert len(output.outputs) == num_output_beams
        for beam_idx, beam in enumerate(output.outputs):
            if gather_generation_logits:
                gen_logits = beam.generation_logits
                assert gen_logits is not None
                assert gen_logits.ndim == 2
                assert gen_logits.shape[0] == sampling_params.max_tokens
            else:
                assert beam.generation_logits is None

            if return_log_probs:
                assert len(beam.logprobs) == sampling_params.max_tokens
            else:
                assert len(beam.logprobs) == 0
            # Check output similarity
            assert similar(
                beam.text,
                expected_outputs[input_prompts[output_idx]][beam_idx])

#!/usr/bin/env python3
import os
from typing import Optional

import click

from tensorrt_llm import LLM as TorchLLM
from tensorrt_llm._tensorrt_engine import LLM
from tensorrt_llm.llmapi import KvCacheConfig, SamplingParams


@click.command()
@click.option("--model_dir", type=str, required=True)
@click.option("--tp_size", type=int, required=True)
@click.option("--engine_dir", type=str, default=None)
@click.option("--n", type=int, default=1)
@click.option("--best_of", type=int, default=None)
@click.option("--top_k", type=int, default=1)
@click.option("--use_beam_search", is_flag=True)
@click.option("--use_pytorch", is_flag=True)
def main(model_dir: str, tp_size: int, engine_dir: Optional[str], n: int,
         best_of: Optional[int], top_k: int, use_beam_search: bool,
         use_pytorch: bool):
    if use_pytorch:
        llm = TorchLLM(
            model_dir,
            tensor_parallel_size=tp_size,
            kv_cache_config=KvCacheConfig(free_gpu_memory_fraction=0.4))
    else:
        llm = LLM(model_dir,
                  tensor_parallel_size=tp_size,
                  kv_cache_config=KvCacheConfig(free_gpu_memory_fraction=0.4))

    if engine_dir is not None and os.path.abspath(
            engine_dir) != os.path.abspath(model_dir):
        llm.save(engine_dir)

    sampling_params = SamplingParams(max_tokens=10,
                                     end_id=-1,
                                     n=n,
                                     best_of=best_of,
                                     use_beam_search=use_beam_search,
                                     top_k=top_k)
    print(sampling_params)
    prompt_token_ids = [45, 12, 13]
    for output in llm.generate([prompt_token_ids],
                               sampling_params=sampling_params):
        print(output)

    print("run_llm.py Done")


if __name__ == '__main__':
    main()

import os

import pytest
from utils.llm_data import llm_models_root
from utils.util import force_ampere, similar

from tensorrt_llm import LLM, SamplingParams
from tensorrt_llm._torch.pyexecutor.llm_request import (LlmRequest,
                                                        SamplingConfig)
from tensorrt_llm.llmapi.llm_utils import KvCacheConfig


@pytest.fixture(scope="module")
def input_prompts():
    return [
        "Born in north-east France, Soyer trained as a",
        "The future of AI is",
    ]


@pytest.fixture(scope="module")
def expected_outputs():
    return {
        "Born in north-east France, Soyer trained as a": [
            "lawyer and was a member of the French Resistance",
            "cook before turning to painting."
        ],
        "The future of AI is": [
            "all about human-machine collaboration.",
            "more promising than you think."
        ],
    }


@pytest.fixture(scope="module")
def llm():
    return LLM(model=os.path.join(llm_models_root(), "llama-models-v2",
                                  "TinyLlama-1.1B-Chat-v1.0"),
               kv_cache_config=KvCacheConfig(max_tokens=1000),
               max_batch_size=8,
               max_seq_len=64,
               disable_overlap_scheduler=True)


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("n", [1, 2, 3])
def test_create_child_request(n: int):
    sampling_config = SamplingConfig()
    setattr(sampling_config, 'top_p', [0.9])
    setattr(sampling_config, 'num_return_sequences', n)

    parent = LlmRequest(
        request_id=1,
        max_new_tokens=10,
        input_tokens=[1, 2, 3],
        sampling_config=sampling_config,
        is_streaming=False,
        client_id=50,
        return_log_probs=True,
        return_context_logits=True,
    )

    for child_id in range(
            parent.request_id + 1,
            parent.request_id + parent.sampling_config.num_return_sequences):
        parent.create_child_request(child_id)

    assert len(parent.child_requests
               ) == parent.sampling_config.num_return_sequences - 1

    for ind, child in enumerate(parent.child_requests):
        assert child.request_id == ind + parent.request_id + 1
        assert child.py_request_id == child.request_id
        assert child.parent_request_id == parent.request_id

        assert child.py_client_id == 50
        assert child.py_max_new_tokens == 10

        assert child.py_return_log_probs == parent.py_return_log_probs
        assert child.py_return_context_logits == parent.py_return_context_logits

        assert child.py_batch_idx is None

        # Verify parent - child independence
        assert child.py_result is not None
        assert child.py_result is not parent.py_result
        assert child.get_tokens() == parent.get_tokens()
        assert child.get_tokens() is not parent.get_tokens()

        assert child.child_requests == []


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("n", [2])
@pytest.mark.parametrize("best_of", [None, 3])
@pytest.mark.threadleak(enabled=False)
def test_n_outputs(n: int, best_of: int, llm, input_prompts, expected_outputs):
    sampling_params = SamplingParams(
        n=n,
        best_of=best_of,
        temperature=0.8,  # ensure different outputs
        top_p=0.95,  # ensure different outputs
        use_beam_search=False)
    for output_idx, output in enumerate(
            llm.generate(input_prompts, sampling_params=sampling_params)):

        assert len(output.outputs) == n

        for idx, sequence in enumerate(output.outputs):
            if n == best_of:
                assert similar(sequence.text,
                               expected_outputs[input_prompts[output_idx]][idx])


@pytest.mark.parametrize("n", [3])
@pytest.mark.threadleak(enabled=False)
def test_async_n_outputs(n: int, llm, input_prompts):
    sampling_params = SamplingParams(
        n=n,
        temperature=0.8,  # ensure different outputs
        top_p=0.95,  # ensure different outputs
        use_beam_search=False)

    # Asynchronously submit many requests to exceed max batch size.
    futures = []
    for _ in range(5):
        for prompt in input_prompts:
            future = llm.generate_async(prompt, sampling_params)
            futures.append(future)

    # Expect no error raised and each result contains n outputs.
    for _, future in enumerate(futures):
        request_output = future.result()
        assert len(request_output.outputs) == n

